#include <vector>

using namespace std;

class Solution {
public:
    bool circularArrayLoop(vector<int>& nums) {
        int n = nums.size();
        auto next = [&](int i) {
            return ((i + nums[i]) % n + n) % n;
        };

        for (int i = 0; i < n; ++i) {
            if (!nums[i]) continue;
            int slow = i, fast = next(i);
            while (nums[slow] * nums[fast] > 0 && nums[slow] * nums[next(fast)] > 0) {
                if (slow == fast) {
                    if (slow == next(slow)) break;
                    return true;
                }
                slow = next(slow);
                fast = next(next(fast));
            }

            int j = i;
            while (nums[j] * nums[next(j)] > 0) {
                int tmp = j;
                j = next(j);
                nums[tmp] = 0;
            }
        }
        return false;
    }
};
